/* From Uiverse.io by sonex-ICB  - Tags: simple, form, login form, subscribe */
.__UIV_SCOPE__ .input,
.__UIV_SCOPE__ .btn {
  border: 0;
  outline: 0;
  padding: 10px;
  text-align: center;
  font-weight: 700;
  color: gray;
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
  font-size: 14px;
  border-radius: 18px 18px 0px 0px;
}
.__UIV_SCOPE__ .btn {
  border-radius: 0px 0px 18px 18px;
  background-color: #c6cf9b;
  color: #f6eca9;
  cursor: pointer;
  transition: 0.5s;
}
.__UIV_SCOPE__ .form {
  padding: 4px;
  background-color: #f6eca9;
  display: flex;
  flex-direction: column;
  border-radius: 18px;
  box-shadow: 0px 0px 3px 1px #c6cf9b;
}
.__UIV_SCOPE__ .form:hover {
  box-shadow: 0px 0px 3px 1px rgb(162, 157, 157);
}
.__UIV_SCOPE__ .btn:hover {
  background-color: #f6eca9;
  color: #c6cf9b;
}
